<style
  scoped
  lang="scss"
  src="./gms-configure-report-modal-filters-tab.scss"
></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import SelectionMenu from "../../selection-menu/selection-menu";
import { SelectionMenuMode } from "../../selection-menu/selection-menu.constants";
import ReportFilters from "../../report-filters/report-filters";

@Component({
  components: {
    SelectionMenu,
    ReportFilters,
  },
})
export default class GmsConfigureReportFiltersTab extends Vue {
  @Prop({
    type: Array,
  })
  initialFilters;

  @Prop({
    type: Object,
    default: () => ({ types: [], config: {} }),
  })
  filterConfig;

  // ENUMS
  SelectionMenuMode = SelectionMenuMode;
}
</script>

<template>
  <div class="FiltersTab">
    <h4 class="FiltersTab__Title">Manage your report's filters below</h4>
    <ReportFilters
      :initialFilters="initialFilters"
      :filterConfig="filterConfig"
      @onFiltersChanged="(filters) => $emit('onFiltersChanged', filters)"
    />
  </div>
</template>
